#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

const int mod = 1000000007;

int power(int a, int k) {
    int ret = 1;
    while (k) {
        if (k & 1) ret = 1LL * ret * a % mod;
        a = 1LL * a * a % mod;
        k >>= 1;
    }
    return ret;
}

int main() {
    int n, m, a, b, k;
    scanf("%d%d%d%d%d", &n, &m, &a, &b, &k);

    int invB = power(b, mod - 2);
    int p = 1LL * a * invB % mod;
    int q = 1LL * ((b - a + mod) % mod) * invB % mod;

    vector<int> P(m + 1), S(m + 1);
    int c = 1;
    for (int i = 0; i <= min(k, m); ++i) {
        P[i] = 1LL * c * power(p, i) % mod * power(q, k - i) % mod;
        c = 1LL * c * (k - i) % mod * power(i + 1, mod - 2) % mod;
    }

    S[0] = P[0];
    for (int i = 1; i <= m; ++i)
        S[i] = (S[i - 1] + P[i]) % mod;

    vector<int> previous(m + 1), current(m + 1), g(m + 1);

    for (int l = 1; l <= m; ++l) {
        previous[l] = (previous[l - 1]
            + 1LL * P[l - 1] * S[m - l]) % mod;
    }

    for (int i = 2; i <= n; ++i) {
        g[0] = 1LL * P[0] * previous[m] % mod;
        for (int r = 1; r <= m; ++r) {
            g[r] = (g[r - 1]
                + 1LL * P[r] * previous[m - r]) % mod;
        }

        current[0] = 0;
        for (int l = 1; l <= m; ++l) {
            int delta = (previous[m - l + 1] - previous[m] + mod) % mod;
            int v = (g[m - l] + 1LL * S[m - l] * delta) % mod;
            current[l] = (current[l - 1]
                + 1LL * P[l - 1] * v) % mod;
        }

        previous.swap(current);
    }

    printf("%d\n", previous[m]);
    return 0;
}

#include <cstdio>
using namespace std;

const int MOD = 1000000007;
const int MAXN = 2005;

int n, m, a, b, k;
int f[MAXN][MAXN], g[MAXN], P[MAXN], S[MAXN];

int power(long long a, int e) {
    long long result = 1;
    a %= MOD;
    while (e) {
        if (e & 1) result = result * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return (int)result;
}

int main() {
    scanf("%d%d%d%d%d", &n, &m, &a, &b, &k);

    int invB = power(b, MOD - 2);
    int p = 1LL * a * invB % MOD;
    int q = 1LL * ((b - a + MOD) % MOD) * invB % MOD;

    int c = 1;
    for (int i = 0; i <= k && i < MAXN; ++i) {
        P[i] = 1LL * c * power(p, i) % MOD * power(q, k - i) % MOD;
        if (i < k) {
            c = 1LL * c * (k - i) % MOD * power(i + 1, MOD - 2) % MOD;
        }
    }

    S[0] = P[0];
    for (int i = 1; i <= m; ++i) {
        S[i] = (S[i - 1] + P[i]) % MOD;
    }

    for (int l = 1; l <= m; ++l) {
        f[1][l] = (f[1][l - 1] + 1LL * P[l - 1] * S[m - l]) % MOD;
    }

    for (int i = 2; i <= n; ++i) {
        g[0] = 1LL * P[0] * f[i - 1][m] % MOD;
        for (int r = 1; r <= m; ++r) {
            g[r] = (g[r - 1] + 1LL * P[r] * f[i - 1][m - r]) % MOD;
        }

        for (int l = 1; l <= m; ++l) {
            int t = m - l;
            int delta = (f[i - 1][t + 1] - f[i - 1][m] + MOD) % MOD;
            int value = (g[t] + 1LL * S[t] * delta) % MOD;
            f[i][l] = (f[i][l - 1] + 1LL * P[l - 1] * value) % MOD;
        }
    }

    printf("%d\n", f[n][m]);
    return 0;
}

